"use client";

// A4 browser print: the user chooses "Save as PDF" in the print dialog.
// No PDF bytes or public URLs are generated by this page.
import { Suspense, useEffect, useState } from "react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { supabase } from "@/lib/supabaseClient";
import type { EpubBookModel, EpubContentBlock } from "@/lib/parari/epub/buildEpubModel";

function plainText(value: string): string {
  // This first PDF version intentionally does not typeset ruby or rich inline markup.
  return value.replace(/\[\[([^|｜\]]+)[|｜]([^\]]+)\]\]/g, "$1")
    .replace(/\[\[([^\]]+)\]\]\(([^)]+)\)/g, "$1")
    .replace(/\*\*([^*]+)\*\*/g, "$1")
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, "$1");
}

function safeImageUrl(url: string): string | undefined {
  if (/^https?:\/\//i.test(url) || (url.startsWith("/") && !url.startsWith("//"))) return url;
  return undefined;
}

function PrintBlock({ block }: { block: EpubContentBlock }) {
  if (block.type === "text") {
    return <div className="pdf-paragraphs">{plainText(block.text)}</div>;
  }
  if (block.type === "image") {
    const url = safeImageUrl(block.url);
    return url ? <figure className="pdf-figure"><img src={url} alt={block.caption ?? ""} />{block.caption ? <figcaption>{block.caption}</figcaption> : null}</figure> : null;
  }
  if (block.type === "aside") {
    return <aside className="pdf-note">{block.title ? <h3>{block.title}</h3> : null}<div className="pdf-paragraphs">{plainText(block.text)}</div></aside>;
  }
  if (block.type === "list") {
    return <section>{block.title ? <h3>{block.title}</h3> : null}<ul>{block.items.map((item, i) => <li key={i}>{plainText(item)}</li>)}</ul></section>;
  }
  if (block.type === "link") {
    const safe = /^https?:\/\//i.test(block.url) ? block.url : undefined;
    return <p>{safe ? <a href={safe}>{block.label}</a> : block.label}</p>;
  }
  if (block.type === "table") {
    return <div className="pdf-table-wrapper"><table>
      {block.caption ? <caption>{block.caption}</caption> : null}
      {block.header && block.rows[0] ? <thead><tr>{block.rows[0].map((cell, i) => <th key={i}>{plainText(cell)}</th>)}</tr></thead> : null}
      <tbody>{block.rows.slice(block.header ? 1 : 0).map((row, i) =>
        <tr key={i}>{row.map((cell, j) => <td key={j}>{plainText(cell)}</td>)}</tr>
      )}</tbody>
    </table></div>;
  }
  return null;
}

function PrintDocument({ model }: { model: EpubBookModel }) {
  return <article className="pdf-document">
    <header className="pdf-cover">
      <h1>{model.title}</h1>
      {model.subtitle ? <p>{model.subtitle}</p> : null}
      {model.author ? <p className="pdf-author">{model.author}</p> : null}
    </header>
    {model.items.map(item => <section key={item.id} className={item.kind === "chapter" ? "pdf-chapter" : "pdf-page"}>
      {item.showTitle && item.title ? item.kind === "chapter" ? <h2>{item.title}</h2> : <h3>{item.title}</h3> : null}
      {item.subtitle ? <p className="pdf-subtitle">{item.subtitle}</p> : null}
      {item.blocks.map((block, index) => <PrintBlock key={index} block={block} />)}
    </section>)}
  </article>;
}

function PdfPrintContent() {
  const params = useSearchParams();
  const workId = params.get("workId");
  const [model, setModel] = useState<EpubBookModel | null>(null);
  const [message, setMessage] = useState("保存済み作品を読み込んでいます…");
  useEffect(() => {
    let canceled = false;
    async function load() {
      try {
        if (!workId) throw new Error("作品IDがありません。");
        const { data: { session } } = await supabase.auth.getSession();
        if (!session?.access_token) throw new Error("ログインしてください。");
        const response = await fetch("/api/pdf/print-model", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${session.access_token}` },
          body: JSON.stringify({ workId }),
          cache: "no-store",
        });
        const result = await response.json() as { model?: EpubBookModel; message?: string };
        if (!response.ok || !result.model) throw new Error(result.message ?? "作品を読み込めませんでした。");
        if (!canceled) {
          setModel(result.model);
          setMessage("");
        }
      } catch (error) {
        if (!canceled) setMessage(error instanceof Error ? error.message : "作品を読み込めませんでした。");
      }
    }
    void load();
    return () => { canceled = true; };
  }, [workId]);

  return <main className="pdf-print-root">
    <style>{`
      @page { size: A4 portrait; margin: 17mm 16mm; }
      .pdf-print-root { color: #171717; background: #eee; min-height: 100vh; }
      .pdf-toolbar { display:flex; flex-wrap:wrap; gap:12px; align-items:center; padding:16px; background:white; border-bottom:1px solid #ddd; }
      .pdf-document { box-sizing:border-box; max-width:210mm; padding:17mm 16mm; margin:20px auto; background:white; box-shadow:0 2px 16px #0002; font: 11pt/1.75 "Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif; overflow-wrap:anywhere; }
      .pdf-cover { margin-bottom:25mm; text-align:center; padding-top:20mm; }
      .pdf-cover h1 { font-size:22pt; line-height:1.4; }
      .pdf-author { margin-top:20mm; }
      .pdf-chapter { break-before:page; }
      .pdf-document h2 { font-size:17pt; margin:2em 0 .6em; }
      .pdf-document h3 { font-size:13pt; margin:1.4em 0 .6em; }
      .pdf-paragraphs { white-space:pre-wrap; margin:0 0 1em; }
      .pdf-note { border-left:3px solid #888; padding:.3em 1em; margin:1em 0; background:#f7f7f7; }
      .pdf-figure { text-align:center; margin:1.4em 0; break-inside:avoid; }
      .pdf-figure img { max-width:100%; max-height:180mm; object-fit:contain; }
      .pdf-figure figcaption { font-size:9pt; }
      .pdf-table-wrapper { overflow-x:auto; margin:1em 0; }
      .pdf-document table { border-collapse:collapse; width:100%; font-size:9pt; }
      .pdf-document td,.pdf-document th { border:1px solid #aaa; padding:.35em; text-align:left; }
      .pdf-document tr { break-inside:avoid; }
      .pdf-document a { color:inherit; text-decoration:underline; }
      @media print {
        .pdf-print-root { background:white; min-height:0; }
        .pdf-toolbar { display:none!important; }
        .pdf-document { max-width:none; margin:0; padding:0; box-shadow:none; }
        .pdf-chapter:first-of-type { break-before:auto; }
      }
    `}</style>
    <nav className="pdf-toolbar">
      <Link href="/my/works" className="text-sm underline">作品一覧へ</Link>
      <strong>PDFで保存する</strong>
      <span className="text-sm text-neutral-600">A4縦・横書き。日本語のルビ・縦書きには対応していません。</span>
      {model ? <button onClick={() => window.print()} className="rounded-lg bg-neutral-900 px-4 py-2 text-sm font-bold text-white">印刷画面を開く（PDFとして保存）</button> : null}
    </nav>
    {message ? <p role="status" className="p-5">{message}</p> : null}
    {model ? <PrintDocument model={model} /> : null}
  </main>;
}

export default function PdfPrintPage() {
  return <Suspense fallback={<p className="p-5">印刷用画面を読み込んでいます…</p>}>
    <PdfPrintContent />
  </Suspense>;
}
